const VADUVUR_INFO={id:"vaduvur-wetland",name:"Vaduvur Wetland & Bird Sanctuary",localName:"Vaduvur Birds Sanctuary (வடுவூர் பறவைகள் சரணாலயம்)",location:"Vaduvur, Tiruvarur District, Tamil Nadu, India",state:"Tamil Nadu",coordinates:{lat:10.7024,lng:79.3175},area:"1.28 km² (128.10 hectares)",establishedYear:1999,ramsarYear:2022,ramsarSiteNo:2480,wetlandType:"Human-made Freshwater Irrigation Tank",riverBasin:"Vennar Sub-basin (Cauvery Delta River System)",climate:"Tropical Wet-and-Dry",bestTime:"November to March (Peak Migratory Season)",nearestTransport:{town:"Mannargudi (14 km) / Thanjavur (25 km)",airport:"Tiruchirappalli International Airport (TRZ - 80 km)",railway:"Thanjavur Junction (25 km) / Mannargudi Railway Station (14 km)"},quickStats:[{label:"Ramsar Site Designated",value:"2022 (No. 2480)",icon:"💧"},{label:"Sanctuary Area",value:"128.10 Hectares",icon:"🌾"},{label:"Wintering Waterfowl",value:"20,000+ Birds",icon:"🦅"},{label:"Sanctuary Established",value:"November 1999",icon:"🏛️"},{label:"Avian Diversity",value:"100+ Species",icon:"🦩"},{label:"Central Asian Flyway",value:"CAF Key Refuge",icon:"🌐"}]},VADUVUR_SECTIONS={history:{title:"History & Evolution",subtitle:"From a early 20th-century Cauvery Delta irrigation reservoir to a internationally recognized Ramsar Site.",paragraphs:["Vaduvur Wetland originated in 1919 as a human-made irrigation tank created to store seasonal floodwaters from the Vennar River—a major distributary of the sacred Cauvery River system. Built to secure water for double-crop paddy farming across the fertile Cauvery Delta, the tank gradually developed into a thriving wetland ecosystem as vegetation and fish populations flourished.","Recognizing its ecological significance as a refuge for thousands of wintering waterfowl, the Government of Tamil Nadu declared Vaduvur Tank a protected Bird Sanctuary under the Wildlife Protection Act, 1972 in November 1999. In August 2022, its global ecological importance was solidified when UNESCO Ramsar Convention designated Vaduvur Wetland as Ramsar Site No. 2480."]},ramsarSite:{title:"Ramsar Site Designation",subtitle:"Globally recognized Wetland of International Importance (Site No. 2480)",paragraphs:["Vaduvur Wetland was officially designated as a Ramsar Site on August 3, 2022 (Ramsar Site No. 2480), covering an area of 128.10 hectares. The designation highlights its critical role in maintaining biological diversity in the semi-arid agricultural landscape of the Cauvery Delta.","As an indispensable stopover on the Central Asian Flyway (CAF), Vaduvur provides vital staging, feeding, and roosting grounds for trans-continental migratory waterfowl travelling from Eurasia, Siberia, Central Asia, and the High Himalayas during the harsh northern winters."]},irrigationTank:{title:"Irrigation Tank Wetland Ecosystem",subtitle:"A classic example of traditional South Indian tank irrigation sustaining rich biodiversity.",paragraphs:["Vaduvur is a classic Tamil Nadu 'Eri' (irrigation tank wetland)—a human-modified shallow water body bounded by earthen bunds and fed by canals from the Lower Anicut and Vennar river system. The wetland stores monsoon rainwater, recharging underground aquifers while supplying water to hundreds of hectares of surrounding rice paddies.","To enhance bird habitat, forest authorities planted mounds of Acacia nilotica (Babul) trees within the tank bed. These submerged tree islands create safe nesting platforms insulated from terrestrial predators like jackals and stray dogs, allowing large colonies of storks, pelicans, and cormorants to breed side-by-side with local farming activities."]},aquaticBiodiversity:{title:"Aquatic Biodiversity",subtitle:"Rich freshwater flora and fish fauna forming a robust food web.",paragraphs:["The freshwater lake harbors diverse macrophyte vegetation including submerged species such as Hydrilla verticillata, Vallisneria spiralis, and Najas minor, alongside floating water lilies (Nymphaea pubescens) and sacred lotus (Nelumbo nucifera). These aquatic plants oxygenate the water and provide spawning nursery grounds for fish.","The wetland supports a rich ichthyofauna including major carps (Catla catla, Labeo rohita, Cirrhinus mrigala), snakeheads (Channa striata), freshwater catfish (Clarias batrachus), and glassfish. This abundant fish supply sustains thousands of fish-eating birds like Spot-billed Pelicans, Oriental Darters, Kingfishers, and Herons."]},conservation:{title:"Conservation & Community Protection",subtitle:"Harmonious co-existence between local farming communities and migratory waterfowl.",paragraphs:["Vaduvur Wetland is managed by the Tamil Nadu Forest Department (Tiruvarur Forest Division). Conservation measures include regular desiltation of feeder channels, removal of invasive weeds such as Water Hyacinth (Eichhornia crassipes) and Prosopis juliflora, perimeter fencing, and anti-poaching watchtowers.","A defining hallmark of Vaduvur is community guardianship. Local villagers regard the arriving winter birds as harbingers of good fortune and agricultural prosperity. During the breeding season (November to March), villagers voluntarily ban firecrackers, loud percussion, and loud speakers during festivals to prevent startling nesting parent birds and their chicks."]}},INTERESTING_FACTS=[{title:"Festival of Wings & No Firecrackers",icon:"🎆",fact:"Villagers surrounding Vaduvur sanctuary voluntarily abstain from bursting firecrackers during Diwali and temple festivals to protect nesting migratory parent birds and chicks."},{title:"Acacia Tree Nesting Islets",icon:"🌳",fact:"Submerged mounds planted with Acacia nilotica (Babul) inside the water tank serve as safe predator-free island nurseries for pelicans, storks, and egrets."},{title:"Cauvery Delta Oasis",icon:"🌾",fact:"Located right in the heart of Tamil Nadu's rice bowl, Vaduvur demonstrates how traditional agricultural irrigation tanks double as world-class wildlife sanctuaries."},{title:"Trans-Continental Traveler Refuge",icon:"✈️",fact:"Waterfowl travel over 5,000 kilometers along the Central Asian Flyway from Siberia, Mongolia, and Central Asia to spend winter in Vaduvur's mild climate."},{title:"Dual Hydrological Role",icon:"💧",fact:"Vaduvur acts as both a flood control buffer during heavy North-East Monsoons and a crucial groundwater recharge source for surrounding agricultural wells."},{title:"Spot-Billed Pelican Haven",icon:"🦩",fact:"Vaduvur hosts one of the largest breeding colonies of the globally Near Threatened Spot-billed Pelican in Southern India."}],BIRD_SPECIES=[{id:"eurasian-wigeon",name:"Eurasian Wigeon",scientificName:"Mareca penelope",category:"waterfowl",status:"Least Concern",season:"November to March (Migratory)",diet:"Aquatic vegetation, seeds, grasses",wingspan:"75–86 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Eurasian_Wigeon_Anas_penelope.jpg/800px-Eurasian_Wigeon_Anas_penelope.jpg",description:"Medium-sized dabbling duck with chestnut head and creamy yellow crown stripe in males. Grazes on aquatic weeds and shore grasses in large flocks."},{id:"northern-pintail",name:"Northern Pintail",scientificName:"Anas acuta",category:"waterfowl",status:"Least Concern",season:"November to March (Migratory)",diet:"Seeds, aquatic plants, invertebrates",wingspan:"80–95 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Northern_Pintail_Anas_acuta.jpg/800px-Northern_Pintail_Anas_acuta.jpg",description:"Elegant dabbling duck with elongated needle-like tail feathers, chocolate-brown neck, and white breast. Rapid long-distance flyer from Siberia."},{id:"spot-billed-pelican",name:"Spot-billed Pelican",scientificName:"Pelecanus philippensis",category:"wading-birds",status:"Near Threatened",season:"October to April (Breeding Resident)",diet:"Freshwater fish",wingspan:"140–150 cm",icon:"🦩",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Spot-billed_Pelican_Pelecanus_philippensis.jpg/800px-Spot-billed_Pelican_Pelecanus_philippensis.jpg",description:"Large greyish-white pelican featuring dark spots on its pink bill pouch. Nests atop submerged Acacia tree canopy mounds inside Vaduvur tank."},{id:"garganey",name:"Garganey",scientificName:"Spatula querquedula",category:"waterfowl",status:"Least Concern",season:"November to March (Migratory)",diet:"Aquatic insects, small mollusks, seeds",wingspan:"58–69 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Garganey_Spatula_querquedula.jpg/800px-Garganey_Spatula_querquedula.jpg",description:"Small migratory dabbling duck characterized by a broad white crescent stripe over the eye in breeding males. Skitters actively over shallow waters."},{id:"oriental-darter",name:"Oriental Darter",scientificName:"Anhinga melanogaster",category:"wading-birds",status:"Near Threatened",season:"Year-round Resident",diet:"Fish, amphibians",wingspan:"115–120 cm",icon:"🦅",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Oriental_Darter_Anhinga_melanogaster.jpg/800px-Oriental_Darter_Anhinga_melanogaster.jpg",description:"Also known as the Snakebird, this slender waterbird impales fish with its dagger-like bill before tossing them into the air to swallow."},{id:"black-headed-ibis",name:"Black-headed Ibis",scientificName:"Threskiornis melanocephalus",category:"wading-birds",status:"Near Threatened",season:"October to March (Breeding Resident)",diet:"Fish, frogs, crustaceans, aquatic insects",wingspan:"110–120 cm",icon:"🪶",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Black-headed_Ibis_Threskiornis_melanocephalus.jpg/800px-Black-headed_Ibis_Threskiornis_melanocephalus.jpg",description:"Striking white wading bird with featherless black head, neck, and down-curved bill. Probes soft wetland mud for aquatic prey."},{id:"painted-stork",name:"Painted Stork",scientificName:"Mycteria leucocephala",category:"wading-birds",status:"Near Threatened",season:"October to April (Breeding)",diet:"Small fish, frogs",wingspan:"150–160 cm",icon:"🪶",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Painted_Stork_Mycteria_leucocephala.jpg/800px-Painted_Stork_Mycteria_leucocephala.jpg",description:"Large heavy-billed stork with yellow face, pink tertiary wing feathers, and black-and-white breast band. Breeds in dense tree colonies."},{id:"common-teal",name:"Common Teal",scientificName:"Anas crecca",category:"waterfowl",status:"Least Concern",season:"November to March (Migratory)",diet:"Seeds, aquatic invertebrates",wingspan:"53–59 cm",icon:"🦆",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Eurasian_Teal_Anas_crecca.jpg/800px-Eurasian_Teal_Anas_crecca.jpg",description:"Tiny dabbling duck with chest-chestnut head and bright green eye band in males. Extremely agile in flight and feeds in shallow marsh edges."}],MAP_HOTSPOTS=[{id:"main-entrance",title:"Sanctuary Main Gate & Visitor Center",category:"visitor-facilities",lat:10.7042,lng:79.316,type:"Visitor Center",description:"Entry point featuring interpretive signage, ticket counter, binoculars rental, and parking facilities."},{id:"north-watchtower",title:"Northern Observation Watchtower",category:"viewpoints",lat:10.7065,lng:79.3185,type:"Observation Tower",description:"Elevated multi-story watchtower offering panoramic views across the central open water tank and roosting trees."},{id:"acacia-islets",title:"Acacia Roosting Tree Islets",category:"ecological-zones",lat:10.702,lng:79.3175,type:"Breeding Colony",description:"Submerged mounds planted with Acacia nilotica trees where Spot-billed Pelicans, Darters, and Storks construct nests."},{id:"bund-trail",title:"Lakeside Bund Eco-Trail",category:"trails",lat:10.6995,lng:79.3155,type:"Walking Track",description:"Tree-shaded 2.5 km walking track atop the tank's earthen embankment, popular for quiet morning bird watching."},{id:"south-lagoon",title:"South-Western Shallow Wading Lagoon",category:"ecological-zones",lat:10.698,lng:79.319,type:"Feeding Ground",description:"Shallow mudflat zone frequented by dabbling ducks like Eurasian Wigeon, Pintails, and Teal foraging for aquatic plants."}],GALLERY_IMAGES=[{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Spot-billed_Pelican_Pelecanus_philippensis.jpg/800px-Spot-billed_Pelican_Pelecanus_philippensis.jpg",caption:"Spot-billed Pelican roosting on Acacia tree branches in Vaduvur Tank",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Northern_Pintail_Anas_acuta.jpg/800px-Northern_Pintail_Anas_acuta.jpg",caption:"Northern Pintail flock swimming in the shallow waters of Vaduvur",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Black-headed_Ibis_Threskiornis_melanocephalus.jpg/800px-Black-headed_Ibis_Threskiornis_melanocephalus.jpg",caption:"Black-headed Ibis foraging along the muddy tank edges",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Painted_Stork_Mycteria_leucocephala.jpg/800px-Painted_Stork_Mycteria_leucocephala.jpg",caption:"Painted Stork perched near tree mounds during peak nesting season",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Eurasian_Wigeon_Anas_penelope.jpg/800px-Eurasian_Wigeon_Anas_penelope.jpg",caption:"Eurasian Wigeon drake floating gracefully near lotus patches",category:"Avian Wildlife"},{url:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Oriental_Darter_Anhinga_melanogaster.jpg/800px-Oriental_Darter_Anhinga_melanogaster.jpg",caption:"Oriental Darter expanding its wings to dry in early morning sun",category:"Avian Wildlife"}];"undefined"!=typeof module&&module.exports&&(module.exports={VADUVUR_INFO:VADUVUR_INFO,VADUVUR_SECTIONS:VADUVUR_SECTIONS,INTERESTING_FACTS:INTERESTING_FACTS,BIRD_SPECIES:BIRD_SPECIES,MAP_HOTSPOTS:MAP_HOTSPOTS,GALLERY_IMAGES:GALLERY_IMAGES});